class Solution { public:
    bool validPartition(vector<int>& nums) {
        int n=nums.size();vector<char> dp(n+1,0);dp[0]=1;
        for(int i=2;i<=n;++i){
            if(nums[i-1]==nums[i-2]&&dp[i-2])dp[i]=1;
            if(i>=3&&dp[i-3]&&((nums[i-1]==nums[i-2]&&nums[i-2]==nums[i-3]) ||
                (nums[i-3]+1==nums[i-2]&&nums[i-2]+1==nums[i-1])))dp[i]=1;
        }
        return dp[n];
    }
};
